package com.vignesh.banking.security;
import org.springframework.context.annotation.*;import org.springframework.security.authentication.*;import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.*;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration @EnableMethodSecurity public class SecurityConfig{ private final JwtAuthFilter f; public SecurityConfig(JwtAuthFilter f){this.f=f;} @Bean SecurityFilterChain chain(HttpSecurity h) throws Exception{ h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**").permitAll().requestMatchers("/api/admin/**").hasRole("ADMIN").requestMatchers("/api/**").authenticated().anyRequest().permitAll()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class); return h.build(); } @Bean PasswordEncoder encoder(){return new BCryptPasswordEncoder();} @Bean AuthenticationManager auth(AuthenticationConfiguration c) throws Exception{return c.getAuthenticationManager();} }
